  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `item_id` int(11) NOT NULL,
  `category` enum('etcitem','weapon','armor') NOT NULL DEFAULT 'etcitem',
  `server` tinyint(4) NOT NULL DEFAULT '0',
  `item_name` varchar(50) NOT NULL,
  `price_sell` double(10,2) NOT NULL DEFAULT '0.00',
  `count` int(4) NOT NULL DEFAULT '0',
  `description` varchar(250) NOT NULL,
  `active` enum('0','1') NOT NULL DEFAULT '1',
  `single` enum('0','1') NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`)
) ENGINE=MyISAM AUTO_INCREMENT=3 DEFAULT CHARSET=cp1251;

