-- ----------------------------
-- Table structure for `stress_donate_wm`
-- ----------------------------
DROP TABLE IF EXISTS `stress_donate_wm`;
CREATE TABLE `stress_donate_wm` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `wm_rnd` varchar(8) NOT NULL,
  `wm_account` varchar(30) NOT NULL DEFAULT '',
  `wm_type` enum('wmz','wmr','wme','wmu') NOT NULL DEFAULT 'wmz',
  `wm_count` double(10,2) NOT NULL DEFAULT '0.00',
  `wm_money` double(10,2) NOT NULL DEFAULT '0.00',
  `wm_time` int(11) NOT NULL DEFAULT '0',
  `wm_ip` varchar(30) NOT NULL DEFAULT '',
  `wm_stage` enum('0','I','E','P','S') NOT NULL DEFAULT '0',
  `wm_success` enum('0','1') NOT NULL DEFAULT '0',
  `payer_wm` varchar(12) NOT NULL DEFAULT '0',
  `payer_wmid` varchar(13) NOT NULL DEFAULT '0',
  `sys_invs_no` varchar(11) NOT NULL DEFAULT '0',
  `sys_trans_no` varchar(11) NOT NULL DEFAULT '0',
  `sys_trans_date` varchar(17) NOT NULL DEFAULT '0',
  `wm_comment` text NOT NULL,
  PRIMARY KEY (`id`),
  KEY `wm_rnd` (`wm_rnd`)
) ENGINE=MyISAM AUTO_INCREMENT=6 DEFAULT CHARSET=cp1251;

